      ],
      "assessment": {
        "nobel_worthiness": "Squeezed light makes quantum noise a controllable resource and has enabled interferometers to surpass important classical limits, including in gravitational-wave detection.",
        "attribution": "Caves established the theoretical framework, Kimble advanced its optical implementation, and Mavalvala helped realize its decisive use in interferometry; the proposed three span theory and practice.",
        "maturity": "The principle is experimentally established and now contributes to operating gravitational-wave detectors.",
        "uncertainties": [
          "The work has a broad contributor base, and the relative credit for the conceptual proposal, laboratory demonstrations, and detector implementation is contestable."
        ]
      }
    },
