      "proposed_laureates": [
        "Jocelyn Bell Burnell"
      ],
      "assessment": {
        "nobel_worthiness": "The discovery of pulsars revealed an entirely new class of compact astronomical objects and provided precise tests of fundamental physics.",
        "attribution": "Bell Burnell's role in recognizing the first pulsar signal is direct and central; the single-name attribution is appropriate to the stated discovery.",
        "maturity": "Pulsars have been studied for decades, with many independent discoveries and lasting importance across astrophysics.",
        "uncertainties": [
          "The original discovery was made within a research group, and the precise division of credit beyond the credited discoverer is not captured here."
        ]
      }
    },
